#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_set_valid_index(void) {
    // Setup: create a vector with some initial data
    Vector* vec = helper_create_vector(0);
    TEST_ASSERT_NOT_NULL(vec);

    // Fill vector with values [10, 20, 30]
    int values[] = {10, 20, 30};
    int fill_result = helper_fill_vector(vec, values, 3);
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    // Verify initial state
    assert_vector_length(vec, 3);
    assert_vector_contents(vec, 0, 10);
    assert_vector_contents(vec, 1, 20);
    assert_vector_contents(vec, 2, 30);

    // Test: set element at valid index (index < vec->len)
    // This triggers the target path: index < vec->len -> vec->contents[index] = val
    set(vec, 1, 99);  // Change element at index 1 from 20 to 99

    // Assertions: verify the value was updated
    assert_vector_contents(vec, 1, 99);

    // Verify other elements unchanged
    assert_vector_contents(vec, 0, 10);
    assert_vector_contents(vec, 2, 30);

    // Verify length unchanged
    assert_vector_length(vec, 3);

    // Cleanup
    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_set_valid_index);
    return UNITY_END();
}

